-- V2 — Cấu hình thi: preset, 11 bài, 23 bước nhỏ, bảng lỗi (seed mặc định theo PROMPT.md §3)
CREATE TABLE IF NOT EXISTS SH_PRESET (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY,
  NAME VARCHAR(100) NOT NULL, OWNER_ID BIGINT, IS_TEMPLATE TINYINT NOT NULL DEFAULT 0,
  DETAILED_ENABLED TINYINT NOT NULL DEFAULT 1, IS_ACTIVE TINYINT NOT NULL DEFAULT 1,
  CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS SH_LESSON (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, PRESET_ID BIGINT NOT NULL,
  LESSON_NO INT NOT NULL, NAME VARCHAR(200) NOT NULL,
  ANNOUNCE_TEXT VARCHAR(300), DURATION_SECONDS INT NOT NULL DEFAULT 20,
  SORT_ORDER INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS SH_STEP (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, LESSON_ID BIGINT NOT NULL,
  STEP_NO INT NOT NULL, NAME VARCHAR(200) NOT NULL,
  ANNOUNCE_TEXT VARCHAR(300), DURATION_SECONDS INT NOT NULL DEFAULT 15,
  ENABLED TINYINT NOT NULL DEFAULT 1, SORT_ORDER INT NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS SH_ERROR_RULE (
  ID BIGINT AUTO_INCREMENT PRIMARY KEY, PRESET_ID BIGINT NOT NULL,
  LESSON_NO INT NOT NULL DEFAULT 0, CODE VARCHAR(50) NOT NULL,
  NAME VARCHAR(200) NOT NULL, DEDUCT_POINTS INT NOT NULL DEFAULT 0,
  IS_LIET TINYINT NOT NULL DEFAULT 0, SORT_ORDER INT NOT NULL DEFAULT 0
);
